// ── source: vcx/tests/canonical_annotation_test.v ──
// Tests for the strict-canonical redundant type-ascription strip (I1 identity
// epoch, row 2): an element-level `::T` ascription that bare re-typing of the
// canonical body image reproduces is REDUNDANT — one value, one spelling, one
// Tier-1 address. Load-bearing ascriptions (sized numerics, decimal, bigint,
// duration/period, array types, empty bodies) stay. The attr lane has stripped
// these since D3 (cx_attr_scalar) — locked here alongside the element lane so
// the two lanes can never drift apart again.

fn canon(src string) string {
	return cx.cx_text_canonical(src) or { panic('${err}; src=${src}') }
}

fn hash(src string) string {
	return cx.cx_text_hash(src) or { panic('${err}; src=${src}') }
}

// ── Element-level strips (redundant — bare re-typing reproduces) ────────────

fn test_int_annotation_strips() {
	assert canon('[n::int 1]') == '[n 1]\n'
}

fn test_float_annotation_strips() {
	assert canon('[n::float 1.5]') == '[n 1.5e0]\n'
}

fn test_float_annotation_strips_and_image_carries_the_type() {
	// `1` coerced to float renders `1.0` — the image alone re-types float.
	assert canon('[n::float 1]') == '[n 1.0e0]\n'
}

fn test_bool_annotation_strips() {
	assert canon('[n::bool true]') == '[n true]\n'
}

fn test_null_annotation_strips() {
	assert canon('[n::null null]') == '[n null]\n'
}

fn test_string_annotation_strips_on_plain_word() {
	assert canon('[n::string abc]') == '[n abc]\n'
}

fn test_atom_annotation_strips_to_sigil_form() {
	// The `:x` sigil re-types atom on its own; `[n::atom :x]` double-spells it.
	assert canon('[n::atom x]') == '[n :x]\n'
}

fn test_date_annotation_strips() {
	assert canon('[n::date 2026-08-05]') == '[n 2026-08-05]\n'
}

fn test_datetime_annotation_strips_and_composes_with_utc_z() {
	// Composes with the W-7 pass: offset → Z first, then the strip.
	assert canon('[n::datetime 2026-08-05T10:00:00+02:00]') == '[n 2026-08-05T08:00:00Z]\n'
}

// ── String bodies whose bare image would re-type: strip + QUOTE ─────────────
// (exactly the attr lane's rule — v::string=2026-08-05 emits v='2026-08-05')

fn test_string_annotation_on_date_shaped_body_strips_to_quoted() {
	assert canon('[n::string 2026-08-05]') == "[n '2026-08-05']\n"
}

fn test_string_annotation_on_spaced_body_strips_to_bare_prose() {
	// An interior single space is legit bare body prose — `[n 'a b']` already
	// canonicalizes to `[n a b]` (same TextNode value, pre-existing rule).
	assert canon("[n::string 'a b']") == '[n a b]\n'
	assert hash("[n::string 'a b']") == hash('[n a b]')
}

fn test_string_annotation_on_sigil_shaped_body_strips_to_quoted() {
	assert canon("[n::string ':x']") == "[n ':x']\n"
}

// ── Load-bearing ascriptions stay ────────────────────────────────────────────

fn test_sized_int_annotation_stays() {
	assert canon('[n::i32 5]') == '[n::i32 5]\n'
}

fn test_decimal_annotation_strips_since_2b() {
	// 2b: a fixed-point fraction IS a decimal — the ascription is the
	// second spelling. Integral-image decimals keep it (bare re-types int).
	assert canon('[n::decimal 1.50]') == '[n 1.50]\n'
	assert hash('[n::decimal 1.50]') == hash('[n 1.50]')
	assert canon('[n::decimal 2]') == '[n::decimal 2]\n'
}

fn test_duration_annotation_stays() {
	// Mirrors the attr lane: duration/period are NOT in the auto-recoverable
	// set (D3) — both lanes keep the glued form.
	assert canon('[n::duration 1h30m]') == '[n::duration 1h30m]\n'
}

fn test_array_annotation_stays() {
	assert canon('[n::int[] 1 2 3]') == '[n::int[] 1 2 3]\n'
}

fn test_empty_string_body_strips_annotation_since_w6() {
	// W-6: the empty string survives as `''`, so the ascription is
	// redundant again — one value, one spelling.
	assert canon("[n::string '']") == "[n '']\n"
	assert hash("[n::string '']") == hash("[n '']")
}

fn test_whitespace_only_string_body_strips_annotation() {
	// W-6 companion (owner-ruled): whitespace-only strings survive quoted,
	// so the ascription is redundant here too.
	assert canon("[n::string '  ']") == "[n '  ']\n"
	assert hash("[n::string '  ']") == hash("[n '  ']")
}

fn test_empty_annotated_element_keeps_annotation() {
	assert canon('[n::int]') == '[n::int]\n'
}

// ── Identity consequences (the W: one value, one address) ───────────────────

fn test_redundant_int_annotation_is_hash_equal_to_bare() {
	assert hash('[n::int 1]') == hash('[n 1]')
}

fn test_atom_annotation_is_hash_equal_to_sigil() {
	assert hash('[n::atom x]') == hash('[n :x]')
}

fn test_string_date_shape_is_hash_equal_to_quoted_and_not_to_date() {
	assert hash('[n::string 2026-08-05]') == hash("[n '2026-08-05']")
	assert hash('[n::string 2026-08-05]') != hash('[n 2026-08-05]')
}

fn test_sized_int_is_not_hash_equal_to_bare() {
	assert hash('[n::i32 5]') != hash('[n 5]')
}

// ── Recursion + idempotence ──────────────────────────────────────────────────

fn test_strip_recurses_into_child_elements() {
	out := canon('[r [n::int 1]]')
	assert !out.contains('::int'), 'nested annotation survived: ${out}'
}

fn test_strip_is_idempotent() {
	once := canon('[n::string 2026-08-05]')
	assert canon(once) == once
}

// ── Attr-lane locks (settled behavior — must never drift) ───────────────────

fn test_attr_int_annotation_strips() {
	assert canon('[n v::int=1]') == '[n v=1]\n'
}

fn test_attr_atom_annotation_strips_to_sigil() {
	assert canon('[n v::atom=x]') == '[n v=:x]\n'
}

fn test_attr_string_date_shape_strips_to_quoted() {
	assert canon('[n v::string=2026-08-05]') == "[n v='2026-08-05']\n"
}

fn test_attr_sized_int_annotation_stays() {
	assert canon('[n v::i32=5]') == '[n v::i32=5]\n'
}

// ── source: vcx/tests/canonical_collections_test.v ──
// Tests for spec/canonical.md canonical
// form treatment of collection literals: map-key lex sort, sequence-
// flat hash, array-nested hash, and diff round-trips.
// ── Map key ordering (§2.11.1) ──────────────────────────────────────────────

fn test_map_canonical_sorts_keys_lex() {
	// Insertion order differs; canonical form sorts keys lexicographically.
	src := "[r {zeta: 1, alpha: 2, mu: 3}]"
	out := cx.cx_text_canonical(src) or { panic(err) }
	// Expect alpha → mu → zeta in canonical output.
	a := out.index('alpha') or { panic('alpha missing in: ${out}') }
	m := out.index('mu') or { panic('mu missing in: ${out}') }
	z := out.index('zeta') or { panic('zeta missing in: ${out}') }
	assert a < m, 'expected alpha before mu; out=${out}'
	assert m < z, 'expected mu before zeta; out=${out}'
}

fn test_map_hash_invariant_under_insertion_order() {
	// Two docs that differ only in map insertion order must hash the same
	// after canonicalization.
	a := "[r {alpha: 1, beta: 2, gamma: 3}]"
	b := "[r {gamma: 3, alpha: 1, beta: 2}]"
	hash_a := cx.cx_text_hash(a) or { panic(err) }
	hash_b := cx.cx_text_hash(b) or { panic(err) }
	assert hash_a == hash_b, 'expected equal hashes; got ${hash_a} vs ${hash_b}'
}

fn test_map_eq_invariant_under_insertion_order() {
	a := "[r {alpha: 1, beta: 2}]"
	b := "[r {beta: 2, alpha: 1}]"
	eq := cx.cx_text_eq(a, b) or { panic(err) }
	assert eq
}

fn test_map_canonicalize_recurses_into_nested_map() {
	src := "[r {z: {bb: 1, aa: 2}, a: 3}]"
	out := cx.cx_text_canonical(src) or { panic(err) }
	// Outer map sorts a before z; inner map sorts aa before bb.
	a_pos := out.index('a:') or { panic('a: missing') }
	z_pos := out.index('z:') or { panic('z: missing') }
	assert a_pos < z_pos, 'outer order wrong; out=${out}'
	aa_pos := out.index('aa') or { panic('aa missing') }
	bb_pos := out.index('bb') or { panic('bb missing') }
	assert aa_pos < bb_pos, 'inner order wrong; out=${out}'
}

fn test_map_canonical_is_idempotent() {
	// Canonicalize-of-canonicalize equals canonicalize per §11.4
	// idempotence requirement.
	src := "[r {zeta: 1, alpha: 2}]"
	once := cx.cx_text_canonical(src) or { panic(err) }
	twice := cx.cx_text_canonical(once) or { panic(err) }
	assert once == twice
}

// ── Array vs Sequence treatment (hash) ──────────────────────────────────────

fn test_array_hash_preserves_nesting() {
	// `[[1, 2], [3, 4]]` and `[1, 2, 3, 4]` are distinct Array values
	// Their hashes must differ.
	a := '[r [[1, 2], [3, 4]]]'
	b := '[r [1, 2, 3, 4]]'
	hash_a := cx.cx_text_hash(a) or { panic(err) }
	hash_b := cx.cx_text_hash(b) or { panic(err) }
	assert hash_a != hash_b, 'expected distinct hashes; got ${hash_a}'
}

fn test_sequence_hash_flattens() {
	// Sequences flatten on construction per CXDM §1 — they
	// flatten at PARSE time, before canonicalization. So nested and
	// flat sources of the same final sequence hash identically.
	a := '[r ((1, 2), 3)]'
	b := '[r (1, 2, 3)]'
	hash_a := cx.cx_text_hash(a) or { panic(err) }
	hash_b := cx.cx_text_hash(b) or { panic(err) }
	assert hash_a == hash_b, 'expected equal seq-flatten hashes; got ${hash_a} vs ${hash_b}'
}

fn test_sequence_vs_array_hash_distinct() {
	a := '[r (1, 2, 3)]'
	b := '[r [1, 2, 3]]'
	hash_a := cx.cx_text_hash(a) or { panic(err) }
	hash_b := cx.cx_text_hash(b) or { panic(err) }
	assert hash_a != hash_b, 'sequence and array must hash differently; ${hash_a}'
}

// ── Diff round-trips (spec/canonical.md §11.4) ──────────────────────────────

fn test_diff_map_reordered_is_empty() {
	a := "[r {alpha: 1, beta: 2}]"
	b := "[r {beta: 2, alpha: 1}]"
	ch := cx.cx_text_diff(a, b) or { panic(err) }
	assert ch.len == 0, 'expected no changes; got ${ch.map(it.path + " " + it.before + " -> " + it.after)}'
}

fn test_diff_array_value_change_detected() {
	a := '[r [1, 2, 3]]'
	b := '[r [1, 2, 4]]'
	ch := cx.cx_text_diff(a, b) or { panic(err) }
	assert ch.len >= 1, 'expected at least one change'
}

fn test_diff_seq_flatten_no_change() {
	// ((1, 2), 3) flattens to (1, 2, 3) at parse — diff sees them as
	// identical.
	a := '[r ((1, 2), 3)]'
	b := '[r (1, 2, 3)]'
	ch := cx.cx_text_diff(a, b) or { panic(err) }
	assert ch.len == 0
}

// ── source: vcx/tests/canonical_decimal_bigint_test.v ──
// Tests for the I1 row-1 invariant slice (stream 11, rulings L39/L43/L45/L47
// — the parts independent of the bare-fraction 2a/2b question):
//   L43: postfix value ascription `value::T` in collection positions
//        (map values, sequence/array items, map keys) — #485 reversed.
//   L39 defect G: typed carriers REJECT non-conforming tokens (CXER0290) —
//        `::decimal hello-world` parsed silently before.
//   L45 (§6): decimal canonical = fixed-point only (exponent input rejects),
//        no `+`, leading zero required, no negative zero, underscores
//        stripped, trailing zeros PRESERVED (scale is data). bigint =
//        shortest digits; the `::bigint` annotation is retained exactly when
//        the bare token would re-type differently (≤ i64), bare otherwise.
//   L47: decimal/bigint admitted as map keys, type-strict, scale-distinct.

fn expect_reject(src string, why string) {
	if _ := cx.parse(src) {
		assert false, '${why}: ${src} must reject'
	}
}

// ── L43: postfix value ascription in collection positions ────────────────────

fn test_postfix_decimal_in_map_value() {
	assert canon('[a {p: 19.99::decimal}]') == '[a {p: 19.99}]\n'
}

fn test_postfix_decimal_in_sequence_items() {
	assert canon('[a (1.10::decimal, 2.05::decimal)]') == '[a (1.10, 2.05)]\n'
}

fn test_postfix_ascription_scale_is_identity() {
	assert hash('[a {p: 1.10::decimal}]') != hash('[a {p: 1.1::decimal}]')
}

fn test_postfix_non_type_suffix_refuses() {
	// RULED: MSS-3 item 4 (#917, supersedes the 831-1a′ pin here): a bare
	// `::`-carrying token in a collection slot either ascribes or REFUSES —
	// it never silently becomes text (that lane also invented values:
	// 'prose ::bool' → false). The quoted spelling is the text form.
	expect_reject('[a {k: some::text}]', 'unknown tag never silently text')
	assert canon("[a {k: 'some::text'}]") == "[a {k: 'some::text'}]\n"
}

fn test_postfix_invalid_payload_fails_loud() {
	expect_reject('[a {p: hello::decimal}]', 'postfix decimal of non-numeric')
}

// ── MSS-1..4 (#917): the map-syntax settlement, data reading ────────────────

fn test_mss2_ws_separated_entries() {
	// RULED: MSS-2 — whitespace separates entries exactly as a comma does.
	assert canon('[m {a: 1 b: 2}]') == '[m {a: 1, b: 2}]\n'
	// Top-level bare-map documents key-sort under strict canonical — the
	// ws-separated spelling lands in the same image as the comma spelling.
	assert canon('{tenant: 5 journal: 6}') == '{journal: 6, tenant: 5}\n'
	assert hash('[m {a: 1 b: 2}]') == hash('[m {a: 1, b: 2}]')
}

fn test_mss1_prose_values_refuse() {
	// RULED: MSS-1 — a map value is ONE expression-shaped item; prose is
	// quoted. The old slot-as-body absorption made `{a: 1 b: 2}` a ONE-entry
	// map with the junk string '1 b: 2' at rc=0 (#917's root exhibit).
	expect_reject('[m {note: hello world}]', 'unquoted prose map value')
	expect_reject('[m {note: warning: check}]', 'colon-bearing bare value')
	expect_reject('[m {u: http://x/y}]', 'unquoted url value')
	assert canon("[m {note: 'hello world'}]") == "[m {note: 'hello world'}]\n"
	// Single bareword values stay legal.
	assert canon('[m {status: active}]') == '[m {status: active}]\n'
}

fn test_mss3_invention_lanes_refuse() {
	// RULED: MSS-3 items 1+2 — checked coercion on EVERY tag arm and the
	// split applies to single ws-free tokens only. These four all parsed at
	// rc=0 before, two of them INVENTING values ({order: false}).
	expect_reject('{order ::ref compact ::bool}', 'spaced glue never an atom entry')
	expect_reject('[m {x: hello there ::bool}]', 'prose ::bool invented false')
	expect_reject('[m {x: hi ::date}]', 'prose ::date invented a garbage date')
	expect_reject('[m {a: maybe::bool}]', 'bool coercion is checked')
	expect_reject('[m {a: 2026-13-99::date}]', 'date coercion is checked')
	expect_reject('[m {a: 5::bogus}]', 'unknown tag never silently text')
	expect_reject('[m [1, reboot now ::bool]]', 'array prose with :: must quote')
}

fn test_mss3_spaced_glue_refuses() {
	// RULED: MSS-3 item 3 — after a key, `::` is never the entry separator
	// (the old byte scan read `{a ::int}` as the atom entry `{a: :int}`).
	expect_reject('[m {a ::int}]', 'spaced annotation after key')
	expect_reject('[p {a ::int c: 3}]', '#917 exhibit — was silent mangle')
	// The atom value stays writable with the glued separator.
	assert canon('[m {a: :int}]') == '[m {a: :int}]\n'
}

fn test_mss3_quoted_glue_rules() {
	// RULED: MSS-3 item 5 — quoted keys take the same checked ascription as
	// bare keys (identity is (kind, image)); quoted VALUES take none.
	assert canon("[m {'1.10'::decimal: x}]") == '[m {1.10: x}]\n'
	assert hash("[m {'1.10'::decimal: x}]") == hash('[m {1.10::decimal: x}]')
	expect_reject("[m {'k'::int: 5}]", 'quoted-key ascription is checked')
	expect_reject("[m {a: '5'::int}]", 'quoted value takes no ascription')
}

fn test_mss3_double_quoted_keys() {
	// RULED: MSS-3 item 7 — both quote forms are QuotedText [L87] in the
	// data reading too (the program reading always accepted them).
	assert canon('[m {"my key": 1}]') == "[m {'my key': 1}]\n"
	assert hash('[m {"my key": 1}]') == hash("[m {'my key': 1}]")
}

fn test_mss4_declaration_entries() {
	// RULED: MSS-4 — `{k: ::T}` declares the field: kind T, value ABSENT.
	// Canonical form round-trips; the kind vocabulary is [157] KindName.
	assert canon('[m {a: ::int}]') == '[m {a: ::int}]\n'
	// Strict canonical key-sorts map entries; ws- and comma-separated
	// spellings land in one image, declarations kept.
	assert canon('[m {order: ::string compact: ::bool, tags: ::string[]}]') == '[m {compact: ::bool, order: ::string, tags: ::string[]}]\n'
	assert canon('[m {view: ::element, sel: ::path}]') == '[m {sel: ::path, view: ::element}]\n'
	// Declared-absent is NOT null — distinct canonical images and hashes.
	assert hash('[m {a: ::int}]') != hash('[m {a: null}]')
	expect_reject('[m {a: ::bogus}]', 'declaration kind vocabulary is closed')
}

// ── MSS-7 (#917, owner "1a"): the prefix family completes ────────────────────

fn test_mss7_prefix_typed_values() {
	// `::T VALUE` types the value through the same checked core as the
	// postfix form — the spelling the owner reached for three times.
	// (strict canonical key-sorts and bares name-safe strings)
	assert canon("[m {name: 'Alice', age: ::int 30, active: true}]") == '[m {active: true, age: 30, name: Alice}]\n'
	// annotation-iff-retyping: load-bearing tags carry, redundant drop —
	// prefix and postfix land in ONE canonical image.
	assert canon('[m {p: ::decimal 2}]') == '[m {p: 2::decimal}]
'
	assert hash('[m {p: ::decimal 2}]') == hash('[m {p: 2::decimal}]')
	assert hash('[m {age: ::int 30}]') == hash('[m {age: 30}]')
	// array/sequence value slots take the same rule.
	assert canon('[m [1, ::int 30, ::decimal 2]]') == '[m [1, 30, 2::decimal]]
'
	assert canon('[m (::string hello, 2)]') == '[m (hello, 2)]
'
	// declaration-vs-value disambiguation: the next entry's key restores.
	assert canon('[m {a: ::int b: 2}]') == '[m {a: ::int, b: 2}]
'
	assert canon('[m {a: ::int 30 b: 2}]') == '[m {a: 30, b: 2}]
'
	// kinds declare only; payloads stay checked; slots need values.
	expect_reject('[m {v: ::element 5}]', 'kind-only tag with a value')
	expect_reject('[m {a: ::int soon}]', 'prefixed payload is checked')
	expect_reject('[m [1, ::int]]', 'array slot declaration')
}

// ── L39 defect G: strict typed carriers ──────────────────────────────────────

fn test_decimal_rejects_non_numeric() {
	expect_reject('[a::decimal hello-world]', 'defect G decimal')
}

fn test_decimal_rejects_exponent_form() {
	// Exponent input makes the scale ambiguous — fixed-point only (§6).
	expect_reject('[a::decimal 1.5e2]', 'decimal exponent form')
}

fn test_bigint_rejects_fraction() {
	expect_reject('[a::bigint 1.5]', 'bigint fraction')
}

fn test_duration_rejects_non_span() {
	expect_reject('[a::duration hello]', 'defect G duration')
}

// ── L45 §6: decimal canonical normalization (ascribed lane) ──────────────────

fn test_decimal_scale_preserved() {
	assert canon('[a::decimal 1.50]') == '[a 1.50]\n'
	assert hash('[a::decimal 1.50]') != hash('[a::decimal 1.5]')
}

fn test_decimal_plus_sign_strips() {
	assert canon('[a::decimal +1.50]') == '[a 1.50]\n'
}

fn test_decimal_leading_zero_required() {
	assert canon('[a::decimal .5]') == '[a 0.5]\n'
}

fn test_decimal_redundant_leading_zeros_strip() {
	assert canon('[a::decimal 007.10]') == '[a 7.10]\n'
}

fn test_decimal_negative_zero_normalizes_scale_kept() {
	assert canon('[a::decimal -0.00]') == '[a 0.00]\n'
}

fn test_decimal_spellings_share_an_address() {
	assert hash('[a::decimal +1.50]') == hash('[a::decimal 1.50]')
	assert hash('[a::decimal .5]') == hash('[a::decimal 0.5]')
}

// ── L45: bigint normalization + annotation-iff-retyping ──────────────────────

fn test_bigint_leading_zeros_strip() {
	assert canon('[a::bigint 007]') == '[a::bigint 7]\n'
}

fn test_small_bigint_keeps_annotation() {
	// Bare `42` would re-type int — the annotation is load-bearing.
	assert canon('[a::bigint 42]') == '[a::bigint 42]\n'
}

fn test_over_i64_bigint_drops_annotation() {
	// Bare over-i64 auto-promotes to bigint ([L20]) — annotation redundant.
	assert canon('[a::bigint 99999999999999999999]') == '[a 99999999999999999999]\n'
	assert hash('[a::bigint 99999999999999999999]') == hash('[a 99999999999999999999]')
}

fn test_bigint_negative_zero_normalizes() {
	assert canon('[a::bigint -0]') == '[a::bigint 0]\n'
}

// ── L47: map keys ─────────────────────────────────────────────────────────────

fn test_decimal_map_key_admitted() {
	assert canon('[a {1.10::decimal: x}]') == '[a {1.10: x}]\n'
}

fn test_decimal_map_keys_scale_distinct() {
	assert hash('[a {1.10::decimal: x}]') != hash('[a {1.1::decimal: x}]')
}

fn test_bigint_key_type_strict_vs_int() {
	// `{1:} ≠ {1::bigint:} ≠ {1.0:}` — three distinct keys.
	assert hash('[a {1: x}]') != hash('[a {1::bigint: x}]')
	assert hash('[a {1: x}]') != hash('[a {1.0: x}]')
}

fn test_duration_map_key_rejects() {
	expect_reject('[a {1h::duration: x}]', 'duration map key')
}

// ── Idempotence ───────────────────────────────────────────────────────────────

fn test_decimal_bigint_canonical_idempotent() {
	for src in ['[a::decimal +1.50]', '[a::bigint 007]', '[a {p: 19.99::decimal}]',
		'[a::bigint 99999999999999999999]', '[a {1.10::decimal: x}]'] {
		once := canon(src)
		assert canon(once) == once, 'not a fixpoint for: ${src}'
	}
}

// ── source: vcx/tests/canonical_float_test.v ──
// Tests for I1 row-2 L18 (W-14-float) + W-3: CX-OWNED Ryū float formatting
// per canonical.md §2.5, and loud rejection of non-finite floats (§1.3 — no
// canonical form exists).
//
// §2.5 rules pinned here: shortest round-trip digits (Ryū); always a decimal
// point (`1.0`, never `1`); scientific only when SHORTER than fixed (tie →
// fixed); lowercase `e`; no `+` and no zero-padding in the exponent; mantissa
// always carries `.` (`1.0e10`, never `1e10`); `-0.0` distinct from `0.0`.
// Previously the emitter rode V's `f64.str()` (`1e+20`, `1e-07`, no mantissa
// dot) — a V upgrade could have silently re-hashed the world.

// ── Fixed forms ──────────────────────────────────────────────────────────────

fn test_simple_floats_stable() {
	assert canon('[a 1.5]') == '[a 1.5]\n'
	assert canon('[a 0.1]') == '[a 0.1]\n'
	assert canon('[a 123.456]') == '[a 123.456]\n'
	assert canon('[a -2.5]') == '[a -2.5]\n'
}

fn test_integral_float_keeps_point() {
	// 2b: floats are exponent-always; 150.0 bare is a DECIMAL (bytes stable).
	assert canon('[a::float 1]') == '[a 1.0e0]\n'
	assert canon('[a 150.0]') == '[a 150.0]\n'
}

fn test_tie_prefers_fixed() {
	// 0.0001: fixed `0.0001` (6) vs sci `1.0e-4` (6) — tie → fixed.
	assert canon('[a 0.0001]') == '[a 0.0001]\n'
}

fn test_negative_zero_distinct() {
	// 2b: bare -0.0 is a DECIMAL — negative zero normalizes positive (scale
	// kept). FLOAT negative zero keeps its distinct address via the
	// exponent spelling.
	assert canon('[a -0.0]') == '[a 0.0]\n'
	assert canon('[a -0.0e0]') == '[a -0.0e0]\n'
	assert hash('[a -0.0e0]') != hash('[a 0.0e0]')
}

// ── Scientific forms (only when shorter; §2.5 surface) ───────────────────────

fn test_sci_mantissa_always_has_point() {
	assert canon('[a 1e10]') == '[a 1.0e10]\n'
}

fn test_sci_no_plus_no_zero_padding() {
	// V spelled these `1e+20` / `1e-07`.
	assert canon('[a 1e20]') == '[a 1.0e20]\n'
	assert canon('[a 1e-7]') == '[a 1.0e-7]\n'
}

fn test_sci_when_shorter_only() {
	// 2b: bare 0.00001 is a DECIMAL — fixed-point, scale preserved.
	assert canon('[a 0.00001]') == '[a 0.00001]\n'
	assert canon('[a 1.5e10]') == '[a 1.5e10]\n'
}

fn test_subnormal_shortest() {
	assert canon('[a 5e-324]') == '[a 5.0e-324]\n'
}

// ── One value, one spelling, one address ─────────────────────────────────────

fn test_float_spellings_share_an_address() {
	assert hash('[a 1e10]') == hash('[a 1.0e10]')
	// 2b: fixed-point text is the DECIMAL kind — a different kind, a
	// different address (the kinds are lexically self-describing).
	assert hash('[a 1e10]') != hash('[a 10000000000.0]')
	assert hash('[a 0.00001]') != hash('[a 1.0e-5]')
}

fn test_float_forms_are_idempotent() {
	for src in ['[a 1e10]', '[a 0.00001]', '[a -0.0]', '[a 123.456]', '[a 5e-324]'] {
		once := canon(src)
		assert canon(once) == once, 'not a fixpoint for: ${src}'
	}
}

// ── W-3: non-finite floats have NO canonical form (§1.3) ─────────────────────

fn test_overflowing_literal_has_no_address() {
	if _ := cx.cx_text_canonical('[a 1e400]') {
		assert false, '1e400 must refuse canonicalization (no canonical form, §1.3)'
	} else {
		assert err.msg().contains('canonical'), 'wrong error: ${err.msg()}'
	}
	if _ := cx.cx_text_hash('[a 1e400]') {
		assert false, '1e400 must have no address'
	}
}

fn test_explicit_float_coercion_of_overflow_rejects() {
	if _ := cx.parse('[a::float 1e400]') {
		assert false, '::float 1e400 must fail loud at parse'
	}
}

// ── source: vcx/tests/canonical_mechanical_warts_test.v ──
// Tests for the I1 row-2 Tier-A mechanical warts (canonical_warts_sweep.md §2,
// each ruled "fix to spec, mechanical"):
//   W-1:  `#id` on an otherwise-empty element survives canonicalization
//         (it was silently dropped — `[a #x1]` emitted `[a]`).
//   W-5:  RawText `[# … #]` is CONTENT and is preserved in strict canonical
//         (it was stripped — `[a [#raw#]]` collided with `[a]`).
//   W-6:  the EMPTY string is a value — `[a '']` emits `''` and no longer
//         collides with `[a]`.
//   W-10: a LEADING UTF-8 BOM is consumed (it survived into canonical
//         output and moved the address); a BOM in bare content is CXER0100.

// ── W-1: #id on an empty element ─────────────────────────────────────────────

fn test_id_on_empty_element_survives() {
	// canonicalize_ids renames source spellings to document-order id-N.
	assert canon('[a #x1]') == '[a #id-1]\n'
}

fn test_id_on_empty_element_distinct_address() {
	assert hash('[a #x1]') != hash('[a]')
}

fn test_id_spelling_still_normalizes() {
	// Two spellings of the same declaration remain ONE address (§2.7b).
	assert hash('[a #x1]') == hash('[a #zz]')
}

// ── W-5: RawText preserved ───────────────────────────────────────────────────

fn test_rawtext_survives_canonical() {
	assert canon('[a [#raw#]]') == '[a [#raw#]]\n'
}

fn test_rawtext_distinct_address() {
	assert hash('[a [#raw#]]') != hash('[a]')
}

fn test_rawtext_next_to_child_survives() {
	out := canon('[a [#raw#] [b]]')
	assert out.contains('[#raw#]'), 'RawText dropped: ${out}'
}

// ── W-6: empty string is a value ─────────────────────────────────────────────

fn test_empty_string_body_survives() {
	assert canon("[a '']") == "[a '']\n"
}

fn test_empty_string_no_longer_collides() {
	assert hash("[a '']") != hash('[a]')
}

fn test_empty_string_double_quoted_source_same_address() {
	assert hash('[a ""]') == hash("[a '']")
}

// ── W-6 companion (owner-ruled 2026-08-05): whitespace-only strings are
// values; XML layout whitespace strips at IMPORT ─────────────────────────────

fn test_whitespace_only_string_survives() {
	assert canon("[a ' ']") == "[a ' ']\n"
	assert hash("[a ' ']") != hash('[a]')
	assert hash("[a ' ']") != hash("[a '']")
}

fn test_whitespace_only_string_is_idempotent() {
	once := canon("[a ' ']")
	assert canon(once) == once
}

fn test_xml_layout_whitespace_strips_at_import() {
	doc := cx.parse_xml('<a>\n  <b/>\n</a>') or { panic(err) }
	out := cx.emit_cx(doc)
	assert !out.contains("'"), 'XML layout whitespace leaked into the tree: ${out}'
}

fn test_xml_mixed_content_text_still_significant() {
	doc := cx.parse_xml('<p>hi <em>x</em></p>') or { panic(err) }
	out := cx.emit_cx(doc)
	assert out.contains('hi'), 'mixed-content text lost: ${out}'
}

fn test_single_join_space_between_siblings_stays_bare() {
	// The parser reconstructs the single space between two non-text items
	// (`[p &amp; &lt;]` ⇄ EntityRef, TextNode(' '), EntityRef) — the bare
	// spelling is canonical and round-trips.
	assert canon('[p &amp; &lt;]') == '[p &amp; &lt;]\n'
}

fn test_multi_space_between_siblings_quotes() {
	// Two spaces cannot ride the join — they quote, and round-trip.
	src := "[p &amp; '  ' &lt;]"
	assert canon(src) == '[p &amp; \'  \' &lt;]\n'
	assert canon(canon(src)) == canon(src)
}

// ── W-10: BOM ────────────────────────────────────────────────────────────────

fn test_leading_bom_consumed_and_address_stable() {
	bom := [u8(0xef), 0xbb, 0xbf].bytestr()
	assert canon('${bom}[a 1]') == '[a 1]\n'
	assert hash('${bom}[a 1]') == hash('[a 1]')
}

fn test_mid_content_bom_rejects() {
	bom := [u8(0xef), 0xbb, 0xbf].bytestr()
	if _ := cx.parse('[a x${bom}y]') {
		assert false, 'mid-content BOM must be CXER0100'
	} else {
		assert err.msg().contains('CXER0100'), 'wrong error: ${err.msg()}'
	}
}

fn test_bom_inside_quoted_value_is_content() {
	// Quoted values are verbatim (L23: values never normalized) — U+FEFF
	// inside quotes is legal content and round-trips.
	bom := [u8(0xef), 0xbb, 0xbf].bytestr()
	out := canon("[a 'x${bom}y']")
	assert out.contains(bom), 'quoted U+FEFF must survive: ${out.bytes().hex()}'
}

// ── Idempotence across the mechanicals ───────────────────────────────────────

fn test_mechanicals_are_idempotent() {
	for src in ['[a #x1]', '[a [#raw#]]', "[a '']"] {
		once := canon(src)
		assert canon(once) == once, 'not a fixpoint for: ${src}'
	}
}

// ── source: vcx/tests/canonical_multidoc_test.v ──
// Tests for I1 row-2 L30 (W-27): a LEGAL multi-document CX file has a
// canonical form and therefore a Tier-1 address. Canonical multi-doc =
// each document's strict-canonical fragment joined by `\n---\n`, with the
// file's single trailing LF (W-14). Previously `cx canonical` / `cx hash`
// REJECTED multi-doc input ("use parse_stream for multi-doc input").

fn test_multidoc_has_canonical_form() {
	assert canon('[a 1]\n---\n[b 2]') == '[a 1]\n---\n[b 2]\n'
}

fn test_multidoc_has_an_address() {
	h := hash('[a 1]\n---\n[b 2]')
	// I1 stream 19: addresses are self-describing — sha2-256: + 64 hex.
	assert h.starts_with('sha2-256:') && h.len == 73, h
}

fn test_multidoc_address_distinct_from_concat_and_parts() {
	assert hash('[a 1]\n---\n[b 2]') != hash('[a 1] [b 2]')
	assert hash('[a 1]\n---\n[b 2]') != hash('[a 1]')
}

fn test_single_doc_bytes_unchanged() {
	// The multi-doc entry must not move any single-document address.
	assert canon('[a 1]') == '[a 1]\n'
}

fn test_per_doc_canonicalization_applies() {
	// The full pipeline (here: the row-2 annotation strip) runs per document.
	assert canon('[a::int 1]\n---\n[b::bool true]') == '[a 1]\n---\n[b true]\n'
}

fn test_per_doc_id_numbering() {
	// Documents are independently canonical: id numbering restarts per doc.
	assert canon('[a #x]\n---\n[b #y]') == '[a #id-1]\n---\n[b #id-1]\n'
}

fn test_separator_line_normalizes() {
	// Trailing junk on a separator line is consumed by the reader; the
	// canonical spelling is the bare `---` line.
	assert canon('[a]\n---  \n[b]') == '[a]\n---\n[b]\n'
}

fn test_multidoc_equality_across_spellings() {
	// Different spellings (glued attr annotation vs bare) — same addresses.
	eq := cx.cx_text_eq('[a x=1]\n---\n[b]', '[a x::int=1]\n---\n[b]') or { panic(err) }
	assert eq
}

fn test_multidoc_is_idempotent() {
	once := canon('[a 1]\n---\n[b 2]\n---\n[c]')
	assert canon(once) == once
}

fn test_empty_middle_document_drops() {
	// parse_stream skips empty documents; two docs remain.
	assert canon('[a]\n---\n\n---\n[b]') == '[a]\n---\n[b]\n'
}

// ── §3.12.2 alignment: data-bin hash rides the SAME canonical pipeline ──────

fn test_data_bin_hash_matches_text_hash_for_faithful_doc() {
	src := '[a 1]'
	doc := cx.parse(src) or { panic(err) }
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	dbh := cx.cx_data_bin_hash(bin) or { panic(err) }
	assert dbh == hash(src), 'data-bin hash diverged from the text pipeline'
}

// ── source: vcx/tests/canonical_nfc_names_test.v ──
// Tests for I1 row-2 L23 second half (W-9/W-11): NAMES normalize to Unicode
// NFC at parse — two spellings of one name are ONE name and ONE address —
// while VALUES are never normalized (data fidelity). The tables are
// CX-owned, generated from the pinned UCD 16.0.0 (tools/gen_nfc_tables.v).

// é as one codepoint (U+00E9) vs e + combining acute (U+0301).
const nfc_e = 'é'

const nfd_e = 'é'

// ── the normalizer itself ────────────────────────────────────────────────────

fn test_nfc_ascii_fast_path_identity() {
	assert cx.cx_nfc_name('plain-ascii_name.x') == 'plain-ascii_name.x'
}

fn test_nfc_composes_latin() {
	assert cx.cx_nfc_name('caf${nfd_e}') == 'caf${nfc_e}'
}

fn test_nfc_already_composed_identity() {
	assert cx.cx_nfc_name('caf${nfc_e}') == 'caf${nfc_e}'
}

fn test_nfc_hangul_composes() {
	// 가 (U+AC00) = ᄀ (U+1100) + ᅡ (U+1161).
	assert cx.cx_nfc_name('가') == '가'
	// LVT: 각 (U+AC01) = ᄀ + ᅡ + ᆨ (U+11A8).
	assert cx.cx_nfc_name('각') == '각'
}

fn test_nfc_reorders_combining_marks() {
	// dot-below (U+0323, ccc 220) must precede acute (U+0301, ccc 230):
	// q + acute + dot-below ≡ q + dot-below + acute (NFC canonical order).
	assert cx.cx_nfc_name('q̣́') == cx.cx_nfc_name('q̣́')
}

fn test_nfc_composition_exclusion_stays_decomposed() {
	// U+0958 (DEVANAGARI QA) is composition-excluded: its NFC form is the
	// decomposed pair U+0915 U+093C.
	assert cx.cx_nfc_name('क़') == 'क़'
}

// ── names normalize; one address ─────────────────────────────────────────────

fn test_nfd_element_name_normalizes() {
	assert hash('[caf${nfd_e} 1]') == hash('[caf${nfc_e} 1]')
	assert canon('[caf${nfd_e} 1]') == '[caf${nfc_e} 1]\n'
}

fn test_nfd_attr_name_normalizes() {
	assert hash('[a caf${nfd_e}=1]') == hash('[a caf${nfc_e}=1]')
}

// ── values NEVER normalize ───────────────────────────────────────────────────

fn test_string_values_keep_their_bytes() {
	assert hash("[a 'caf${nfd_e}']") != hash("[a 'caf${nfc_e}']")
}

// ── W-11: NFC duplicate-key comparison ───────────────────────────────────────

fn test_nfc_confusable_map_keys_are_duplicates() {
	if _ := cx.parse("[a {'caf${nfc_e}': 1, 'caf${nfd_e}': 2}]") {
		assert false, 'NFC/NFD confusable keys must be a duplicate-key error'
	} else {
		assert err.msg().contains('DUPKEY'), 'wrong error: ${err.msg()}'
	}
}

// ── idempotence ──────────────────────────────────────────────────────────────

fn test_nfc_names_idempotent() {
	once := canon('[caf${nfd_e} x=1]')
	assert canon(once) == once
}

// ── source: vcx/tests/canonical_quote_escape_test.v ──
// Tests for the I1 row-2 quote-lane rulings (canonical_warts_sweep.md §6,
// owner-ruled (a) 2026-08-05):
//   L15 (W-12): §2.4 escapes are EMITTED — LF/CR/tab as \n \r \t, other C0
//     as \u00xx, DEL as \u007f; quoted canonical text never carries raw
//     control bytes.
//   L16 (W-13): both-quotes tiebreak = single-quoted with \' — the data lane
//     converges on the render lane's rule; one binary, one spelling.
//   L17 (W-2): canonical NEVER emits triquote — multiline values escape.
// The minimal-backslash bijection rule (§2.4) is unchanged: regex surfaces
// like '\d' must not churn.

// ── L17: multiline values escape; triquote never survives ───────────────────

fn test_newline_body_value_escapes() {
	assert canon("[n '''a\nb''']") == "[n 'a\\nb']\n"
}

fn test_escape_spelled_source_is_the_same_address() {
	assert hash("[n '''a\nb''']") == hash("[n 'a\\nb']")
}

fn test_multiline_attr_value_escapes() {
	// [55a] triquote AttValue reads fine; canonical re-emits the escaped
	// single-line single-quoted form.
	assert canon("[n v='''a\nb''']") == "[n v='a\\nb']\n"
}

fn test_no_triquote_in_canonical_output() {
	src := "[doc [a '''line one\nline two'''] [b v='''x\ny'''] [c '''q'\"w''']]"
	out := canon(src)
	assert !out.contains("'''"), 'triquote survived canonicalization: ${out}'
}

// ── L15: §2.4 control-character escapes ──────────────────────────────────────

fn test_cr_escapes() {
	assert canon("[n '''a\rb''']") == "[n 'a\\rb']\n"
}

fn test_tab_in_quoted_value_escapes() {
	// Source spells the tab as an escape; the value carries a raw tab byte;
	// canonical re-emits the \t escape (idempotent fixpoint).
	assert canon("[n 'a\\tb']") == "[n 'a\\tb']\n"
}

fn test_c0_control_escapes_lowercase_u() {
	assert canon("[n 'a\\u0001b']") == "[n 'a\\u0001b']\n"
}

fn test_del_escapes() {
	assert canon("[n 'a\\u007fb']") == "[n 'a\\u007fb']\n"
}

fn test_raw_control_bytes_quote_and_escape() {
	// A raw C0 byte in source quoted text must not pass through verbatim.
	out := canon('[n \'a\u0001b\']')
	assert out == "[n 'a\\u0001b']\n"
}

// ── L16: both-quotes tiebreak = single-quoted with \' ────────────────────────

fn test_both_quotes_forced_quote_ties_to_single() {
	// Leading quote forces quoting (boundary rule); value carries both quote
	// kinds; the tiebreak is single-quoted with \' — never triquote, and the
	// double quote needs no escape inside '…'.
	assert canon('[n "\'a\\"b"]') == "[n '\\'a\"b']\n"
}

fn test_both_quotes_with_triquote_run_ties_to_single() {
	// A '''-run inside the value used to force the verbatim-triquote branch
	// (which then could not hold it) — every ' now escapes individually.
	assert canon('[n "\'\'\'x\\"y"]') == "[n '\\'\\'\\'x\"y']\n"
}

fn test_single_only_value_double_quotes_with_escapes() {
	// has ' but no " → double-quoted (§2.3); a newline inside still escapes.
	assert canon('[n """it\'s' + '\n' + 'here"""]') == '[n "it\'s\\nhere"]\n'
}

// ── Bijection rule unchanged: regex surfaces do not churn ────────────────────

fn test_regex_backslash_does_not_churn() {
	assert canon("[n 'a\\db']") == "[n 'a\\db']\n"
}

// ── Mid-word quotes stay legal bare prose (core 035 family — unchanged) ─────

fn test_midword_quotes_stay_bare() {
	assert canon("[n '''a'b\"c''']") == '[n a\'b"c]\n'
}

// ── Idempotence ──────────────────────────────────────────────────────────────

fn test_quote_escape_canonical_is_idempotent() {
	for src in ["[n '''a\nb''']", '[n "\'a\\"b"]', "[n 'a\\u0001b']",
		"[n v='''a\nb''']"] {
		once := canon(src)
		assert canon(once) == once, 'not a fixpoint for: ${src}'
	}
}

// ── source: vcx/tests/canonical_tagged_address_test.v ──
// Tests for I1 row 3 (stream 19, L31/L32/L35): SELF-DESCRIBING addresses.
// Text-visible addresses are `<multiformats-name>:<lowercase-hex>`
// (sha2-256 default); binary lanes carry varint multihash with a normative
// bijection; bare hex is REJECTED (no dual-accept); unknown algorithms
// fail loud (fail-closed verifiers).

fn test_tier1_address_is_tagged() {
	h := cx.cx_text_hash('[a 1]') or { panic(err) }
	assert h.starts_with('sha2-256:'), h
	assert h.len == 'sha2-256:'.len + 64, h
}

fn test_algo_registry_names() {
	for algo in ['sha2-256', 'sha2-384', 'sha2-512', 'blake3'] {
		h := cx.cx_text_hash_algo('[a 1]', algo) or { panic(err) }
		assert h.starts_with('${algo}:'), h
	}
}

fn test_legacy_names_fail_loud() {
	for legacy in ['sha256', 'sha512', 'b3'] {
		if _ := cx.cx_text_hash_algo('[a 1]', legacy) {
			assert false, 'legacy algo name `${legacy}` must reject (one registry, no dual-accept)'
		}
	}
}

fn test_bare_hex_is_not_an_address() {
	if _, _ := cx.cx_parse_tagged_address('e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855') {
		assert false, 'bare hex must reject'
	} else {
		assert err.msg().contains('CXER0130'), err.msg()
	}
}

fn test_unknown_algo_fails_closed() {
	if _, _ := cx.cx_parse_tagged_address('md5:d41d8cd98f00b204e9800998ecf8427e') {
		assert false, 'unknown algorithm must fail closed'
	} else {
		assert err.msg().contains('CXER0131'), err.msg()
	}
}

fn test_digest_length_mismatch_rejects() {
	if _, _ := cx.cx_parse_tagged_address('sha2-256:abcd') {
		assert false, 'short digest must reject'
	} else {
		assert err.msg().contains('CXER0132'), err.msg()
	}
}

fn test_multihash_text_bijection() {
	h := cx.cx_text_hash('[a 1]') or { panic(err) }
	algo, hex := cx.cx_parse_tagged_address(h) or { panic(err) }
	mut digest := []u8{cap: 32}
	for i := 0; i < hex.len; i += 2 {
		digest << u8(hex[i..i + 2].parse_uint(16, 8) or { panic(err) })
	}
	mh := cx.cx_multihash_encode(algo, digest) or { panic(err) }
	// sha2-256 multihash: 0x12 0x20 + 32 digest bytes.
	assert mh.len == 34 && mh[0] == 0x12 && mh[1] == 0x20, mh.hex()
	algo2, digest2 := cx.cx_multihash_decode(mh) or { panic(err) }
	assert algo2 == algo && digest2 == digest, 'bijection broke'
}

fn test_tier2_address_composes_namespace_and_algo() {
	// code:sha2-256:<hex> — the namespace discriminator stays outermost.
	h := code_tier2_probe()
	assert h.starts_with('sha2-256:'), h
}

fn code_tier2_probe() string {
	return cx.cx_text_hash('[x 1]') or { '' } // Tier-2 composition is pinned in code_identity tests
}

// ── L36: signature-suite registry, fail-closed verifiers ─────────────────────

fn test_suite_registry_gate() {
	if _ := cx.cx_suite_verify_gate('ed25519') {
	} else {
		assert false, 'ed25519 must verify'
	}
	for bad in ['ml-dsa-65', 'unknown-suite', 'rsa-2048'] {
		if _ := cx.cx_suite_verify_gate(bad) {
			assert false, '`${bad}` must fail closed (reserved/unknown/unimplemented)'
		} else {
			assert err.msg().contains('unsupported-suite'), err.msg()
		}
	}
}

// ── source: vcx/tests/canonical_unicode_names_test.v ──
// Tests for I1 row-2 L22 (W-9): the grammar admits full-Unicode names
// ([L10a]/[L10b], XML-derived ranges minus `:`), and the parsers now widen to
// it — `[café]` used to silently degrade to a string. UTF-8 VALIDITY is
// enforced at the data parse entries (L23 first half). NFC normalization of
// names (L23 second half) is the NEXT epoch commit — it needs the UCD tables;
// nothing here pins NFC≡NFD equality yet.

// ── [L10a]/[L10b] acceptance ─────────────────────────────────────────────────

fn test_latin1_supplement_name() {
	assert canon('[café 1]') == '[café 1]\n'
}

fn test_unicode_attr_name() {
	assert canon('[a naïve=1]') == '[a naïve=1]\n'
}

fn test_greek_name() {
	assert canon('[σελίδα x=1]') == '[σελίδα x=1]\n'
}

fn test_cjk_name() {
	// #x3001-#xD7FF covers CJK.
	assert canon('[页 1]') == '[页 1]\n'
}

fn test_astral_plane_name() {
	// #x10000-#xEFFFF: astral codepoints are legal name chars per [L10a].
	assert canon('[𝛼 1]') == '[𝛼 1]\n'
}

fn test_combining_mark_as_continuation() {
	// #x0300-#x036F are NameChar (continuation) — an NFD spelling parses.
	// (NFC-vs-NFD ADDRESS equality lands with the UCD tables — not pinned.)
	// Since the L23 tables landed the NFD spelling NORMALIZES: one name,
	// one address.
	assert canon('[é 1]') == '[é 1]\n'
	h1 := cx.cx_text_hash('[é 1]') or { panic(err) }
	h2 := cx.cx_text_hash('[é 1]') or { panic(err) }
	assert h1 == h2
}

fn test_unicode_name_roundtrips_idempotent() {
	for src in ['[café 1]', '[a naïve=1]', '[页 1]'] {
		once := canon(src)
		assert canon(once) == once, 'not a fixpoint for: ${src}'
	}
}

// ── Characters OUTSIDE the name ranges still reject / stay values ────────────

fn test_non_name_codepoint_is_not_an_element_head() {
	// U+00A9 © is not in [L10a] — the bracket routes to the array/text
	// lane (same as any non-name head, e.g. `[9 1]` → `[9, 1]`), never to
	// an element named `©`.
	assert canon('[© 1]') == "['© 1']\n"
}

fn test_non_name_codepoint_fine_in_body_text() {
	assert canon('[a ©2026]') == '[a ©2026]\n'
}

// ── L23 first half: UTF-8 validity enforced at the data parse entries ────────

fn test_invalid_utf8_rejects() {
	bad := [u8(`[`), `a`, ` `, 0xff, `]`].bytestr()
	if _ := cx.parse(bad) {
		assert false, 'lone 0xFF must reject as invalid UTF-8'
	} else {
		assert err.msg().to_lower().contains('utf-8'), 'wrong error: ${err.msg()}'
	}
}

fn test_overlong_encoding_rejects() {
	// 0xC0 0xAF is the classic overlong `/`.
	bad := [u8(`[`), `a`, ` `, 0xc0, 0xaf, `]`].bytestr()
	if _ := cx.parse(bad) {
		assert false, 'overlong encoding must reject'
	}
}

fn test_truncated_sequence_rejects() {
	// A lead byte with no continuation.
	bad := [u8(`[`), `a`, ` `, `x`, 0xe2, `]`].bytestr()
	if _ := cx.parse(bad) {
		assert false, 'truncated UTF-8 sequence must reject'
	}
}

fn test_surrogate_encoding_rejects() {
	// CESU-8-style encoded surrogate U+D800 = ED A0 80.
	bad := [u8(`[`), `a`, ` `, 0xed, 0xa0, 0x80, `]`].bytestr()
	if _ := cx.parse(bad) {
		assert false, 'encoded surrogate must reject'
	}
}

fn test_valid_multibyte_values_pass() {
	assert canon('[a grüße]') == '[a grüße]\n'
	// An interior single space is legal bare prose — quoted source
	// canonicalizes to the bare spelling (same rule as `[n 'a b']`).
	assert canon("[a '👍 ok']") == '[a 👍 ok]\n'
}

// ── XML lane: non-ASCII element names stay bijective ─────────────────────────

fn test_xml_unicode_name_imports() {
	doc := cx.parse_xml('<café x="1"/>') or { panic(err) }
	out := cx.emit_cx(doc)
	assert out.contains('café'), 'XML unicode name lost: ${out}'
}

// ── #829 (RULED: 829-1c): a mid-run comment is placement-preserved AND
// hash-inert ───────────────────────────────────────────────────────────────
//
// The constraint the fix had to satisfy. #469 closed the run SPLIT because
// splitting a text run into two nodes moves the strict-canonical hash; §2.9
// simultaneously requires "comment placement preserved relative to nodes".
// Both hold now: the run stays ONE node (so the hash is untouched) and the
// comment carries a presentation-only `run_offset` the lossless emitter uses
// to re-place it. These assert the two halves together — if a future change
// ever restores the split to fix placement, the inertness half goes red.

fn test_mid_run_comment_is_hash_inert() {
	assert hash('[config a [; c ] b]') == hash('[config a b]')
	assert hash('[config a [; c ] b [; d ] e]') == hash('[config a b e]')
}

fn test_mid_run_comment_keeps_its_position() {
	assert fmt829('[config a [; c ] b]') == '[config a [; c ] b]'
	assert fmt829('[config a [; c ] b [; d ] e]') == '[config a [; c ] b [; d ] e]'
}

// ── #829 remainder: the ELEMENT-META zone is the OTHER place a comment
// sits that is neither a text run nor a body-item position ─────────────────
//
// `run_offset` cannot reach it — there is no run. Retention worked by
// PREPENDING meta-zone comments to the element's items, and the emitter
// writes attributes before items, so the comment was hoisted past every
// attribute it came before. It now carries its own presentation-only
// `meta_attr_index` (the attribute count it sat after) on exactly the same
// terms: the node does not move, canonical still strips it, and only the CX
// emitter reads the stamp.
//
// Asserted in the same both-halves shape as the mid-run pair above.

fn test_meta_zone_comment_is_hash_inert() {
	assert hash('[config [; c ] env=dev]') == hash('[config env=dev]')
	assert hash('[config env=dev [; c ] port=80]') == hash('[config env=dev port=80]')
	assert hash('[config [; c ] env=dev port=80]') == hash('[config env=dev port=80]')
}

fn test_meta_zone_comment_keeps_its_position() {
	assert fmt829('[config [; c ] env=dev]') == '[config [; c ] env=dev]'
	assert fmt829('[config [; c ] env=dev port=80]') == '[config [; c ] env=dev port=80]'
	assert fmt829('[config env=dev [; c ] port=80]') == '[config env=dev [; c ] port=80]'
}

// A meta-zone comment with NO attribute after it keeps the leading-body-item
// placement it already round-tripped through — in the multiline lane that is
// its own line, which is the shape the #825 work landed and must not move.
fn test_meta_zone_comment_without_a_following_attr_is_unchanged() {
	assert fmt829('[a [;note] text]') == '[a [;note] text]'
	assert fmt829('[a [;c] [b 1]]') == '[a\n  [;c]\n  [b 1]\n]'
}

// fmt829 renders through the LOSSLESS lane (parse → emit), which is where
// comment placement is observable; `canon` above strips comments by design.
fn fmt829(src string) string {
	doc := cx.parse(src) or { panic('${err}; src=${src}') }
	return cx.emit_cx(doc).trim_space()
}
